let _markdown = "\n\n<Wrapper>\n  <div className=\"bg-fd-background rounded-lg prose-no-margin\">\n    ```js title=\"config.js\"\n    import createMDX from 'fumadocs-mdx/config';\n\n    const withMDX = createMDX();\n\n    // [!code word:config]\n    /** @type {import('next').NextConfig} */\n    const config = {\n      // [!code highlight]\n      reactStrictMode: true, // [!code highlight]\n    }; // [!code highlight]\n\n    export default withMDX(config);\n    ```\n  </div>\n</Wrapper>\n\n<Installation name=\"codeblock\" />\n\n<FeedbackBlock\n  id=\"e0d2ac7108ac101e\"\n  body=\"This is a MDX component meant to be used with Rehype Code to display highlighted codeblocks.\nYou can refer to Markdown for the syntax of writing codeblocks.\"\n>\n  This is a **MDX component** meant to be used with [Rehype Code](/docs/headless/mdx/rehype-code) to display highlighted codeblocks.\n  You can refer to [Markdown](/docs/markdown#codeblock) for the syntax of writing codeblocks.\n</FeedbackBlock>\n\n<FeedbackBlock id=\"867bf5586484d3ce\" body=\"Supported features:\">\n  Supported features:\n</FeedbackBlock>\n\n<FeedbackBlock id=\"469be19fa002806a\" body=\"Copy buttonCustom titles and icons\">\n  * Copy button\n  * Custom titles and icons\n</FeedbackBlock>\n\n> <FeedbackBlock id=\"45c84b64bd5ebb2a\" body=\"If you're looking for an equivalent with runtime syntax highlighting, see Dynamic Code Block.\">\n>   If you're looking for an equivalent with runtime syntax highlighting, see [Dynamic Code Block](/docs/ui/components/dynamic-codeblock).\n> </FeedbackBlock>\n\nUsage [#usage]\n\n<FeedbackBlock id=\"ba16885217807f0c\" body=\"Wrap the pre element in <CodeBlock />, which acts as the wrapper of code block.\">\n  Wrap the pre element in `<CodeBlock />`, which acts as the wrapper of code block.\n</FeedbackBlock>\n\n```tsx title=\"mdx-components.tsx\"\nimport defaultComponents from 'fumadocs-ui/mdx';\nimport type { MDXComponents } from 'mdx/types';\nimport { CodeBlock, Pre } from 'fumadocs-ui/components/codeblock';\n\nexport function getMDXComponents(components?: MDXComponents): MDXComponents {\n  return {\n    ...defaultComponents,\n    // HTML `ref` attribute conflicts with `forwardRef`\n    pre: ({ ref: _ref, ...props }) => (\n      <CodeBlock {...props}>\n        <Pre>{props.children}</Pre> {/* [!code highlight] */}\n      </CodeBlock>\n    ),\n    ...components,\n  };\n}\n```\n\nKeep Background [#keep-background]\n\n<FeedbackBlock id=\"66855e6182e92260\" body=\"Use the background color generated by Shiki.\">\n  Use the background color generated by Shiki.\n</FeedbackBlock>\n\n```tsx\nimport { Pre, CodeBlock } from 'fumadocs-ui/components/codeblock';\n\n<CodeBlock keepBackground {...props}>\n  <Pre>{props.children}</Pre>\n</CodeBlock>;\n```\n\nIcons [#icons]\n\n<FeedbackBlock id=\"2d5c84a675fa892c\" body=\"Specify a custom icon by passing an icon prop to CodeBlock component.\">\n  Specify a custom icon by passing an `icon` prop to `CodeBlock` component.\n</FeedbackBlock>\n\n<FeedbackBlock id=\"7e9b89f47b6a790c\" body=\"By default, the icon will be injected by the custom Shiki transformer.\">\n  By default, the icon will be injected by the custom Shiki transformer.\n</FeedbackBlock>\n\n```js title=\"config.js\"\nconsole.log('js');\n```\n";
